WITH valid_subscriptions AS (SELECT *, DATEDIFF(CURRENT_DATE(), end_date) AS days_since_end_date FROM subscriptions WHERE plan IN ('basic', 'enterprise', 'standard') AND monthly_fee < 180 AND customer_id IS NULL), summary AS (SELECT QUARTER(start_date) AS start_quarter, ROUND((100 * SUM(CASE WHEN status = 'CANCELLED' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_cancelled FROM valid_subscriptions GROUP BY QUARTER(start_date)) SELECT * FROM summary WHERE pct_cancelled > 74;
